           precedent='2025 기말 9번(이동 관계 + 블록 적분값 g(k)의 합, OP55·OP36) · LIVE2-03-252(강서고 2021 12번: 초기 함수 x+1) · LIVE2-03-253(대진고 2022 11번: 곱 계수 2x) · 3회 15번(이동 관계식에 계수 붙이기)',
           db_ref='I64 v3_추가 1',
           ops=['OP10', 'OP11', 'OP08', 'OP55', 'OP36', 'OP34', 'OP41', 'OP43'],
